CREATE TABLE`inverters` (  `nombre` varchar(100) NOT NULL,  `y` float NOT NULL,  `power_max` float NOT NULL,  `power` float NOT NULL,  `vmax` float NOT NULL,  `I_max_input` float NOT NULL,  `I_max_output` float NOT NULL,  `id` int NOT NULL AUTO_INCREMENT,  `created_at` datetime DEFAULT NULL,  `updated_at` datetime DEFAULT NULL,  PRIMARY KEY (`id`),  UNIQUE KEY `nombre` (`nombre`)) ENGINE = InnoDB AUTO_INCREMENT = 23 DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci
  
